static REPRESENTATIVE_SOURCE_LOCALES: &[(&str, &str)] = &[
    ("af-za", "af"),
    ("am-et", "am"),
    ("ar-eg", "ar"),
    ("az-az", "az"),
    ("bg-bg", "bg"),
    ("bn-bd", "bn"),
    ("ca-es", "ca"),
    ("cs-cz", "cs"),
    ("da-dk", "da"),
    ("de-de", "de"),
    ("el-gr", "el"),
    ("en-us", "en"),
    ("es-es", "es"),
    ("fa-ir", "fa"),
    ("fi-fi", "fi"),
    ("fil-ph", "fil"),
    ("fr-fr", "fr"),
    ("ha-arab", "ha"),
    ("he-il", "he"),
    ("hi-in", "hi"),
    ("id-id", "id"),
    ("it-it", "it"),
    ("ja-jp", "ja"),
    ("ko-kr", "ko"),
    ("ku-tr", "ku"),
    ("nb-no", "no"),
    ("nn-no", "nn"),
    ("no-no", "no"),
    ("pa-guru-in", "pa"),
    ("pl-pl", "pl"),
    ("pt-br", "pt"),
    ("ro-md", "ro"),
    ("ru-ru", "ru"),
    ("sr-cyrl-rs", "sr"),
    ("sr-latn-rs", "sr-latn"),
    ("sv-se", "sv"),
    ("th-th", "th"),
    ("tr-tr", "tr"),
    ("uk-ua", "uk"),
    ("uz-latn-uz", "uz"),
    ("vi-vn", "vi"),
    ("zh-cn", "zh"),
    ("zh-hant-tw", "zh-hant"),
];

fn representative_source_locale(locale: &str) -> Option<&'static str> {
    REPRESENTATIVE_SOURCE_LOCALES
        .iter()
        .find_map(|&(tag, source)| if tag == locale { Some(source) } else { None })
}

fn locale_candidates(locale: &str) -> [Option<&str>; 3] {
    let normalized = locale.split('.').next().unwrap_or(locale);
    let primary_end = normalized.find('-').unwrap_or(normalized.len());
    let rest = normalized.get(primary_end + 1..).unwrap_or("");
    let second_len = rest.find('-').unwrap_or(rest.len());
    let script_candidate = if second_len == 4 && primary_end + 1 + second_len < normalized.len() {
        Some(&normalized[..primary_end + 1 + second_len])
    } else {
        None
    };
    [
        Some(normalized),
        script_candidate,
        Some(&normalized[..primary_end]),
    ]
}

pub(crate) fn relative_auto(
    locale: &str,
    unit: &str,
    style: &str,
    value: i64,
) -> Option<&'static str> {
    let normalized = locale.replace('_', "-").to_ascii_lowercase();
    if let Some(source_locale) = representative_source_locale(&normalized) {
        for (row_locale, row_unit, row_style, row_value, text) in RELATIVE_ROWS {
            if *row_locale == source_locale
                && *row_unit == unit
                && *row_style == style
                && *row_value == value
            {
                return Some(*text);
            }
        }
    }
    for candidate in locale_candidates(&normalized).into_iter().flatten() {
        for (row_locale, row_unit, row_style, row_value, text) in RELATIVE_ROWS {
            if *row_locale == candidate
                && *row_unit == unit
                && *row_style == style
                && *row_value == value
            {
                return Some(*text);
            }
        }
    }
    None
}

pub(crate) fn numeric_pattern(
    locale: &str,
    unit: &str,
    style: &str,
    is_past: bool,
    count: &str,
) -> Option<&'static str> {
    let normalized = locale.replace('_', "-").to_ascii_lowercase();
    let direction = if is_past { "past" } else { "future" };
    for wanted_count in [count, "other"] {
        if let Some(source_locale) = representative_source_locale(&normalized) {
            for (row_locale, row_unit, row_style, row_direction, row_count, pattern) in PATTERN_ROWS
            {
                if *row_locale == source_locale
                    && *row_unit == unit
                    && *row_style == style
                    && *row_direction == direction
                    && *row_count == wanted_count
                {
                    return Some(*pattern);
                }
            }
        }
        for candidate in locale_candidates(&normalized).into_iter().flatten() {
            for (row_locale, row_unit, row_style, row_direction, row_count, pattern) in PATTERN_ROWS
            {
                if *row_locale == candidate
                    && *row_unit == unit
                    && *row_style == style
                    && *row_direction == direction
                    && *row_count == wanted_count
                {
                    return Some(*pattern);
                }
            }
        }
    }
    None
}
